        if coupon["expires_at"] < now_ts:
            raise ValueError(f"coupon {coupon['code']} has expired")
        if subtotal < Decimal(str(coupon["min_subtotal"])):
            raise ValueError(f"coupon {coupon['code']} requires a minimum subtotal of {coupon['min_subtotal']}")
        rate += Decimal(str(coupon["rate"]))
